/* مصدر مرجع أو تعليقه لا حاجة فيه لوسم أو شيفرة — يُرفض صراحةً */
function _wsAllowedRefUri(v){
  /* مصدر مرجع مقبول بقائمة سماح. أي مخطّط آخر مرفوض افتراضاً، فلا ننتظر
     إضافة نمط هجوم جديد إلى قائمة حظر قبل أن نرفضه. */
  if(typeof v!=='string'||!v) return false;
  const low=v.trim().toLowerCase();
  if(_wsUnsafeRef(low)) return false;
  if(low.indexOf('https:')===0||low.indexOf('http:')===0||low.indexOf('blob:')===0)
    return true;
  if(low.indexOf('data:')===0)
    return low.indexOf('data:image/')===0&&low.indexOf(';base64,')>=0
      &&low.split(',')[0].indexOf('svg')<0;
  if(low.split('/')[0].indexOf(':')>=0) return false;
  return /^[a-z0-9._~/-]+$/.test(low); }
function _wsUnsafeRef(){ const j=Array.prototype.slice.call(arguments)
  .map(v=>String(v===null||v===undefined?'':v)).join(' ').toLowerCase();
  return WS_REFERENCE_UNSAFE.some(p=>j.indexOf(String(p).toLowerCase())>=0); }
